// Generated web files are imported with `with { type: "file" }`, which yields a path string. These declarations
// give that import a type for each extension Vite can emit. Bun's own types already type `*.html` (as an HTML
// bundle), so build.ts converts those imports to paths in web-assets.generated.ts instead.
declare module "*.js" {
  const path: string;
  export default path;
}
declare module "*.css" {
  const path: string;
  export default path;
}
declare module "*.map" {
  const path: string;
  export default path;
}
declare module "*.json" {
  const path: string;
  export default path;
}
declare module "*.svg" {
  const path: string;
  export default path;
}
declare module "*.png" {
  const path: string;
  export default path;
}
declare module "*.jpg" {
  const path: string;
  export default path;
}
declare module "*.webp" {
  const path: string;
  export default path;
}
declare module "*.ico" {
  const path: string;
  export default path;
}
declare module "*.woff" {
  const path: string;
  export default path;
}
declare module "*.woff2" {
  const path: string;
  export default path;
}
